module msg_stream_sink #(parameter DATA_WIDTH=32)(input clk,input rst_n,input valid,output ready,input [DATA_WIDTH-1:0] data,input [7:0] source_id,input [7:0] msg_id,input [63:0] timestamp,output reg [31:0] msg_count); reg [63:0] last_timestamp; assign ready=1'b1; always @(posedge clk or negedge rst_n) if(!rst_n) begin msg_count<=0;last_timestamp<=0; end else if(valid&&ready) begin if(msg_count!=0&&timestamp<last_timestamp)$error("message timestamp decreased"); msg_count<=msg_count+1'b1;last_timestamp<=timestamp;$display("[MSG] source=%0d id=%0d timestamp=%0d data=%h",source_id,msg_id,timestamp,data); end endmodule
